{
  "decision-allocate-freight-overage-with-floor": "WITH RECURSIVE ordered AS (SELECT shipment_id, capacity_used, ROW_NUMBER() OVER (ORDER BY capacity_used, shipment_id) AS pos FROM shipments), allocation(fixed_count, pool, capacity) AS (SELECT 0, 100, SUM(capacity_used) FROM shipments UNION ALL SELECT a.fixed_count + 1, a.pool - 20, a.capacity - o.capacity_used FROM allocation AS a JOIN ordered AS o ON o.pos = a.fixed_count + 1 WHERE a.pool * o.capacity_used < 20 * a.capacity), settled AS (SELECT * FROM allocation ORDER BY fixed_count DESC LIMIT 1), shares AS (SELECT o.shipment_id, CASE WHEN o.pos <= s.fixed_count THEN 20 ELSE s.pool * o.capacity_used / s.capacity END AS base, CASE WHEN o.pos <= s.fixed_count THEN 0 ELSE s.pool * o.capacity_used % s.capacity END AS remainder FROM ordered AS o CROSS JOIN settled AS s), ranked AS (SELECT *, ROW_NUMBER() OVER (ORDER BY remainder DESC, shipment_id) AS priority, 100 - SUM(base) OVER () AS leftover FROM shares) SELECT shipment_id, base + CASE WHEN priority <= leftover THEN 1 ELSE 0 END AS fee_cents FROM ranked ORDER BY shipment_id",
  "decision-allocate-invoice-discount-before-page-subtotals": "WITH active AS (SELECT line_no, page_no, gross_cents, SUM(gross_cents) OVER () AS total_gross FROM charge_line WHERE void_flag = 0), shares AS (SELECT a.*, t.discount_cents, t.discount_cents * a.gross_cents / a.total_gross AS base, t.discount_cents * a.gross_cents % a.total_gross AS remainder FROM active AS a CROSS JOIN invoice_terms AS t), ranked AS (SELECT *, ROW_NUMBER() OVER (ORDER BY remainder DESC, line_no) AS priority, discount_cents - SUM(base) OVER () AS leftover FROM shares), allocated AS (SELECT page_no, gross_cents, base + CASE WHEN priority <= leftover THEN 1 ELSE 0 END AS line_discount FROM ranked) SELECT page_no, SUM(gross_cents) AS gross_cents, SUM(line_discount) AS discount_cents, SUM(gross_cents - line_discount) AS net_cents FROM allocated GROUP BY page_no ORDER BY page_no",
  "decision-allocate-kiln-shelf-space": "WITH lots AS (SELECT lot_id, COALESCE(lot_slots, piece_qty * slots_each) AS slots, mass_kg, priority_pts FROM waiting_lots), candidates(first_id, second_id, slots, mass, points) AS (SELECT lot_id, NULL, slots, mass_kg, priority_pts FROM lots UNION ALL SELECT a.lot_id, b.lot_id, a.slots + b.slots, a.mass_kg + b.mass_kg, a.priority_pts + b.priority_pts FROM lots AS a JOIN lots AS b ON a.lot_id COLLATE BINARY < b.lot_id), best AS (SELECT first_id, second_id FROM candidates WHERE slots <= 10 AND mass <= 12 ORDER BY points DESC, slots, first_id COLLATE BINARY, second_id COLLATE BINARY LIMIT 1) SELECT l.lot_id FROM lots AS l JOIN best AS b ON l.lot_id IN (b.first_id, b.second_id) ORDER BY l.lot_id COLLATE BINARY",
  "decision-allocate-printer-plates-to-chapter-pockets": "SELECT a.pocket_leaf AS first_leaf, b.pocket_leaf AS second_leaf, ABS(a.pocket_leaf - a.opener_leaf) + ABS(b.pocket_leaf - b.opener_leaf) AS drift_leaves, a.setup_min + b.setup_min AS total_min FROM pocket_offer AS a JOIN pocket_offer AS b ON a.pocket_leaf < b.pocket_leaf WHERE a.chapter_no = 1 AND b.chapter_no = 2 AND a.setup_min + b.setup_min <= 7 ORDER BY drift_leaves, total_min, first_leaf, second_leaf LIMIT 1"
}
